import sys
from xml.dom import minidom

doc_path = "unpacked/word/document.xml"
dom = minidom.parse(doc_path)

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local_name(tag):
    return tag.split("}")[-1] if "}" in tag else tag

paras = dom.getElementsByTagNameNS(W, "p")
print(f"Total paragraphs: {len(paras)}")

heading_styles = set()
for p in paras:
    pPr = None
    for child in p.childNodes:
        if child.nodeType == child.ELEMENT_NODE and local_name(child.tagName) == "pPr":
            pPr = child
            break
    style = ""
    if pPr is not None:
        for child in pPr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and local_name(child.tagName) == "pStyle":
                style = child.getAttributeNS(W, "val")
                break
    # Collect text of the paragraph
    texts = []
    for r in p.getElementsByTagNameNS(W, "r"):
        for t in r.childNodes:
            if t.nodeType == t.ELEMENT_NODE and local_name(t.tagName) in ("t", "delText"):
                texts.append(t.firstChild.nodeValue if t.firstChild else "")
    text = "".join(texts).strip()
    if style:
        heading_styles.add(style)
        if any(k in style.lower() for k in ("title", "heading", "head")):
            print(f"STYLE={style!r:20} TEXT={text[:80]!r}")

print("\nAll styles used in paragraphs:")
for s in sorted(heading_styles):
    print(" ", s)

import os
from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local_name(tag):
    return tag.split("}")[-1] if "}" in tag else tag

def para_info(p, idx):
    pPr = None
    for child in p.childNodes:
        if child.nodeType == child.ELEMENT_NODE and local_name(child.tagName) == "pPr":
            pPr = child
            break
    # collect run-level properties of first run
    runs = p.getElementsByTagNameNS(W, "r")
    rpr_info = []
    for r in runs:
        rPr = None
        for child in r.childNodes:
            if child.nodeType == child.ELEMENT_NODE and local_name(child.tagName) == "rPr":
                rPr = child
                break
        props = []
        if rPr is not None:
            for child in rPr.childNodes:
                if child.nodeType == child.ELEMENT_NODE:
                    nm = local_name(child.tagName)
                    if nm == "rFonts":
                        props.append("rFonts:" + child.getAttributeNS(W, "ascii"))
                    elif nm == "sz":
                        props.append("sz:" + child.getAttributeNS(W, "val"))
                    elif nm == "b" or nm == "bCs":
                        props.append(nm)
                    elif nm == "i" or nm == "iCs":
                        props.append(nm)
                    elif nm == "u":
                        props.append("u:" + child.getAttributeNS(W, "val"))
                    elif nm == "color":
                        props.append("color:" + child.getAttributeNS(W, "val"))
                    else:
                        props.append(nm)
        texts = []
        for t in r.childNodes:
            if t.nodeType == t.ELEMENT_NODE and local_name(t.tagName) in ("t", "delText"):
                texts.append(t.firstChild.nodeValue if t.firstChild else "")
        txt = "".join(texts)
        rpr_info.append((txt, ",".join(props)))
    return rpr_info

dom = minidom.parse("unpacked/word/document.xml")
paras = dom.getElementsByTagNameNS(W, "p")
for i, p in enumerate(paras):
    info = para_info(p, i)
    full = "".join(t for t, _ in info)
    props = "; ".join(f"[{t!r}:{pr}]" for t, pr in info if t.strip())
    print(f"--- P{i}: {full!r}")
    if props:
        print(f"    runs: {props}")

